package ro.leo.visual;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Compact menu coverage and real Leo page checks; no communication or setting toggles. */
public final class CompactShellTests extends Instrumentation {
 int checks;Activity page;boolean activate,activated;
 public void onCreate(Bundle b){activate=b!=null&&"true".equals(b.getString("activate"));start();}
 void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 Object field(Object object,String name)throws Exception{for(Class<?> c=object.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(NoSuchFieldException next){}throw new NoSuchFieldException(name);}
 void call(Object object,String name,Class<?>[] types,Object... args)throws Exception{Method m=object.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(object,args);}
 void ui(final Runnable r){final Throwable[] error={null};runOnMainSync(new Runnable(){public void run(){try{r.run();}catch(Throwable t){error[0]=t;}}});if(error[0]!=null)throw new RuntimeException(error[0]);}
 Activity open(Class<?> cls){Activity a=startActivitySync(new Intent(getTargetContext(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();SystemClock.sleep(120);return a;}
 void close(){if(page!=null){final Activity a=page;ui(new Runnable(){public void run(){a.finish();}});page=null;}}
 public void onStart(){final Context base=getTargetContext();final String token="compact-check-"+UUID.randomUUID();final File dir=new File(base.getCacheDir(),token);dir.mkdir();Context fixture=new ContextWrapper(base){public File getFilesDir(){return dir;}public SharedPreferences getSharedPreferences(String name,int mode){return base.getSharedPreferences(token+name,mode);}};SharedPreferences settings=base.getSharedPreferences("settings-ui",0);boolean had=settings.contains("category");int oldCategory=settings.getInt("category",0);Bundle out=new Bundle();try{
 check(Appearance.THEMES.length==Appearance.COLORS.length&&ThemePacks.NAMES.length==ThemePacks.THEMES.length,"style registry complete");
 ThemeCheckpoint.apply(fixture,5,true);check(Appearance.palette(fixture).classic(),"classic palette selected");check(!fixture.getSharedPreferences("appearance",0).getBoolean("list",true),"classic pack selects icon grid");Bitmap wallpaper=BitmapFactory.decodeFile(Appearance.wallpaper(fixture).getPath());check(wallpaper!=null&&wallpaper.getWidth()==240&&wallpaper.getHeight()==302,"classic wallpaper valid");wallpaper.recycle();
 int[] reverse=new int[AppCatalog.NAMES.length];for(int i=0;i<reverse.length;i++)reverse[i]=reverse.length-i-1;AppCatalog.save(fixture,reverse);int[] primary=AppCatalog.menuOrder(fixture,0),all=AppCatalog.menuOrder(fixture,6);check(primary.length==9,"nine primary apps");Set<Integer> root=new HashSet<>(),visible=new HashSet<>(),leaves=new HashSet<>();boolean descending=true;int previous=Integer.MAX_VALUE;for(int id:primary){root.add(id);descending&=id<previous;previous=id;}for(int id:all)visible.add(id);boolean unique=true;for(int group=1;group<=5;group++)for(int id:AppCatalog.menuOrder(fixture,group))unique&=leaves.add(id);check(unique,"single category ownership for every app");check(root.size()==9&&root.contains(0)&&root.contains(2)&&root.contains(8)&&root.contains(9),"phone messages settings and Android apps easy to reach");check(descending,"custom primary order retained");check(visible.equals(leaves)&&visible.containsAll(root),"all remaining apps retained in categories");boolean clean=true;for(int id:visible)clean&=!AppCatalog.settingsOnly(id);check(clean,"settings utilities stay out of launcher");check(Arrays.equals(reverse,AppCatalog.order(fixture)),"filtering does not overwrite saved order");
 if(activate){ThemeCheckpoint.apply(base,5,true);activated=true;}
 page=open(PersonalizationActivity.class);final Activity personal=page;ui(new Runnable(){public void run(){try{check(((List<?>)field(personal,"listRows")).size()==5,"five personalization groups");call(personal,"order",new Class<?>[]{int.class},0);check(((List<?>)field(personal,"listRows")).size()==AppCatalog.menuOrder(base,6).length,"reordering still includes every launcher app");((Runnable)field(personal,"back")).run();check(((List<?>)field(personal,"listRows")).size()==5,"Back returns to personalization groups");}catch(Exception e){throw new RuntimeException(e);}}});close();
 page=open(SettingsActivity.class);final Activity config=page;ui(new Runnable(){public void run(){try{call(config,"switchCategory",new Class<?>[]{int.class},0);check(((List<?>)field(config,"listRows")).size()==6,"network tools grouped");call(config,"switchCategory",new Class<?>[]{int.class},1);check(((List<?>)field(config,"listRows")).size()==3,"appearance duplication reduced");call(config,"switchCategory",new Class<?>[]{int.class},5);check(((List<?>)field(config,"listRows")).size()==6,"six phone settings entries");}catch(Exception e){throw new RuntimeException(e);}}});close();
 page=open(WallpaperActivity.class);final Activity looks=page;ui(new Runnable(){public void run(){try{check(((List<?>)field(looks,"listRows")).size()==5,"five wallpaper/theme entry points");call(looks,"themes",new Class<?>[]{});check(((List<?>)field(looks,"listRows")).size()==Appearance.THEMES.length,"legacy themes remain reachable");}catch(Exception e){throw new RuntimeException(e);}}});close();
 check(Class.forName("com.android.vcard.VCardComposer")!=null,"external dependency loading retained");out.putString("result","PASS "+checks+" compact/classic checks");out.putBoolean("activated",activate);
 }catch(Throwable t){out.putString("error",android.util.Log.getStackTraceString(t));if(activated)try{ThemeCheckpoint.restore(base);}catch(Exception restore){out.putString("restore_error",restore.toString());}}
 finally{close();SharedPreferences.Editor e=settings.edit();if(had)e.putInt("category",oldCategory);else e.remove("category");e.commit();for(String name:new String[]{"appearance","accessibility"})base.getSharedPreferences(token+name,0).edit().clear().commit();File[] files=dir.listFiles();if(files!=null)for(File f:files)f.delete();dir.delete();}finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
